                                                tcsEn[rscI] = rscVa ? rd32(rscVa, rscBase + rscEn) : 0u;
                                                tcsSt[rscI] = rscVa ? rd32(rscVa, rscBase + rscSt) : 0u;
                                                tcsWait[rscI] = rscVa ? rd32(rscVa, rscBase + rscWait) : 0u;
