    if (&native_ufs_log_sync) (void)native_ufs_log_sync();

    gmuW[ADRENO_GMU_BOOT_V1_HFI_QTBL_ADDR] = 0u;
    gmuW[ADRENO_GMU_BOOT_V1_HFI_QTBL_INFO] = 1u;
